const listApprovalProjections = `-- name: ListApprovalProjections :many
WITH readable AS MATERIALIZED (
    SELECT access.project_id,
           project_permission_held(
               access.company_id, access.project_id, access.user_id,
               $14::text,
               $15::text[],
               $16::text[],
               $17::text[]
           ) AS decides
    FROM project_access AS access
    WHERE access.company_id = $1::uuid
      AND access.user_id = $2::uuid
      AND $9::boolean
), company_decider AS MATERIALIZED (
    SELECT EXISTS (
        SELECT 1 FROM company_members AS member
        WHERE member.company_id = $1::uuid
          AND member.user_id = $2::uuid
          AND member.status = 'active'
          AND member.role = ANY($18::text[])
    ) AS decides
)
SELECT
    approvals.id, approvals.company_id, approvals.type, approvals.status, approvals.rule_key, approvals.title, approvals.summary, approvals.preview_markdown, approvals.presentation, approvals.requested_by_agent_id, approvals.origin_run_id, approvals.request_key, approvals.task_id, approvals.conversation_id, approvals.origin_user_id, approvals.canonical_action, approvals.request_sha256, approvals.action_sha256, approvals.expires_at, approvals.decision_note, approvals.decided_by_user_id, approvals.execution_status, approvals.execution_result, approvals.skipped_reason, approvals.continuation_run_id, approvals.continuation_prompt, approvals.continuation_status, approvals.continuation_next_attempt_at, approvals.continuation_abandon_reason, approvals.continuation_attempts, approvals.created_at, approvals.updated_at, approvals.version, approvals.commerce_manifest_id,
    agents.name AS requesting_agent_name,
    decided_users.display_name AS decided_by_display_name,
    decided_users.avatar_url AS decided_by_avatar_url
FROM approvals
JOIN agents
  ON agents.company_id = approvals.company_id
 AND agents.id = approvals.requested_by_agent_id
LEFT JOIN users AS decided_users ON decided_users.id = approvals.decided_by_user_id
LEFT JOIN conversations AS origin_chat
  ON origin_chat.id = approvals.conversation_id
 AND origin_chat.company_id = approvals.company_id
WHERE approvals.type = 'company_plan_apply'
  AND approvals.company_id = $1::uuid
  AND (
      approvals.origin_user_id = $2::uuid
      -- Task origin: read by the readers of the Task chat it was raised in,
      -- so it follows the Project, also after the Task is deleted (ADR 0017).
      OR (approvals.task_id IS NOT NULL AND COALESCE((
          SELECT true FROM conversation_readers AS reader
          WHERE reader.company_id = approvals.company_id
            AND reader.conversation_id = approvals.conversation_id
            AND reader.user_id = $2::uuid
          LIMIT 1
      ), false))
  )
  AND (
      NOT $3::boolean
      OR approvals.status = ANY($4::text[])
  )
  AND (
      NOT $5::boolean
      OR approvals.requested_by_agent_id = $6::uuid
  )
  AND (
      NOT $7::boolean
      OR approvals.task_id = $8::uuid
  )
  AND (
      NOT $9::boolean
      OR CASE
          WHEN approvals.task_id IS NOT NULL
           AND approvals.type = 'company_plan_apply'
           AND origin_chat.kind = 'task'
           AND origin_chat.project_id IS NOT NULL
              THEN origin_chat.project_id IN (SELECT readable.project_id FROM readable WHERE readable.decides)
          ELSE (SELECT company_decider.decides FROM company_decider)
      END
  )
  AND (
      NOT $10::boolean
      OR (approvals.created_at, approvals.id) < (
          $11::timestamptz,
          $12::uuid
      )
  )
ORDER BY approvals.created_at DESC, approvals.id DESC
LIMIT $13::integer
`

